const VIEW_DIST = 400, // The "range of sight" for each particle
			DEBUG = false,  // Show rules?

			presets = [
				false, // 0 is the random preset
				{
					types: 2,
					rules: {0: {0: 1, 1: -1}, 1: {0: 1, 1: 1}}
				},
