				},
				{
					types: 4,
					rules: {0: {0: 1, 1: -1, 2: -1, 3: -1}, 1: {0: 1, 1: 1, 2: -1, 3: -1}, 2: {0: 1, 1: 1, 2: 1, 3: -1}, 3: {0: 1, 1: 1, 2: 1, 3: 1}}
				},
				{
					types: 4,
					rules: {0: {0: -1, 1: 1, 2: -1, 3: -1}, 1: {0: -1, 1: -1, 2: -1, 3: 1}, 2: {0: -1, 1: 1, 2: -1, 3: -1}, 3: {0: 1, 1: 1, 2: 1, 3: 1}}
				},
				{
					types: 2,
					rules: {0: {0: 1, 1: -1}, 1: {0: 1, 1: 0}},
					chances: {0: 0.9, 1: 0.1}
				},
				{
					types: 4,
					rules: {0: {0: 1, 1: 1, 2: 1, 3: -1}, 1: {0: 1, 1: 1, 2: -1, 3: 1}, 2: {0: -1, 1: 1, 2: 1, 3: 1}, 3: {0: 1, 1: -1, 2: 1, 3: 1}}
				}
			]

let particles = [],

		rules = {};

function resetParticles(chances){
	particles = [];
	for(let i = 0; i < 100; i ++){ // If you change this, change the shader too!
		let type;
		if(chances){
			let r = Math.random(),
					v = 0;
			for(let t = 0; t < NUM_TYPES; t ++){
				if(r < chances[t] + v) {
					type = t;
					break;
				} else {
					v += chances[t];
				}
			}
		} else {
			type = Math.floor(Math.random() * (NUM_TYPES - 0.0001));
		}
		particles.push({pos: new p5.Vector(random(width), random(height)), vel: new p5.Vector(), type: type});
	}
}

function createRandomEnvironment (types){
	NUM_TYPES = types;

	colors = new Array(NUM_TYPES).fill().map((_, i) => [1 / NUM_TYPES * i, 1, (Math.random() * 40 + 60) / 100]);
	dataCols = [];

	for(let c of colors){
		dataCols.push(...c);
	}
	metaballShader.setUniform("colors", dataCols);

	for(let i = 0; i < NUM_TYPES; i ++){
		rules[i] = {};

		for(let k = 0; k < NUM_TYPES; k ++){
			rules[i][k] = Math.random() * 2 - 1; // 1 = attract, -1 = repel.
		}
	}

	resetParticles();
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();

	createRandomEnvironment(10);

	if(DEBUG) console.log("Rules: " + JSON.stringify(rules));

	shader(metaballShader);
	metaballShader.setUniform("colors", dataCols);
}

function draw() {
	let data = [];
	for(let particle of particles){
		data.push(particle.pos.x, particle.pos.y, 10, particle.type);

		particle.vel.div(1.1);
		particle.vel.limit(3);
		particle.pos.add(particle.vel);

		let acc = new p5.Vector();
		for(let other of particles){
			if(other === particle) continue
			let d = other.pos.dist(particle.pos) - 20;
			if(d > VIEW_DIST) continue
			acc.add(other.pos.copy().sub(particle.pos).normalize().div(d < 0 ? 0.01/d : Math.pow(d, 0.75)).mult(rules[particle.type][other.type]));
		}

		particle.vel.add(acc.limit(0.3));

		if(particle.pos.x < 20 || particle.pos.x > width - 20) particle.vel.x *= -1
		if(particle.pos.y < 20 || particle.pos.y > height - 20) particle.vel.y *= -1
	}


	metaballShader.setUniform("metaballs", data);
	rect(0, 0, width, height);
}

function keyPressed(){
	if(!isNaN(key)) {
		if(key === '0') {
			createRandomEnvironment(Math.round(Math.random() * 6) + 4);
		} else if(presets[key]){
			NUM_TYPES = presets[key].types;
			colors = new Array(NUM_TYPES).fill().map((_, i) => [1 / NUM_TYPES * i, 1, (Math.random() * 40 + 60) / 100]);
			dataCols = [];

			for(let c of colors){
				dataCols.push(...c);
			}
			metaballShader.setUniform("colors", dataCols);

			rules = Object.assign({}, presets[key].rules);

			resetParticles(presets[key].chances ? presets[key].chances : false);
		}
	}
}

// === Tab: shader ===
let metaballShader;

function preload() {
	metaballShader = getShader(this._renderer);
}

function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec4 metaballs[100];
		uniform vec3 colors[10];

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		vec3 hsv2rgb(vec3 c) // https://stackoverflow.com/questions/15095909/from-rgb-to-hsv-in-opengl-glsl
		{
				vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
				vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
				return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
		}

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			vec3 color;
			for (int i = 0; i < 100; i++) {
				vec4 ball = metaballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				float r = ball.z;

				float weight = r * r / (dx * dx + dy * dy);
				v += weight;

				int ball_type = int(ball.w);
				for (int q = 0; q < 10; q++) { // I feel so stupid doing this, but it's GLSL's fault.
					if(q == ball_type){
						vec3 converted = hsv2rgb(colors[q]);
						color = mix(color, converted, clamp(0.75 * weight, 0.0, 1.0));
						break;
					}
				}
			}

			if (v > 1.0) gl_FragColor = vec4(color.x, color.y, color.z, 1.0);
			else gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
		}
	`;

	return createShader(vert, frag);
}

